import org.eclipse.jface.dialogs.Dialog;
import org.eclipse.jface.window.Window;

class MySelectionDialog extends Dialog {
    protected MySelectionDialog(Window parentShell) {
        super(parentShell.getShell());
    }
    public void configure() {
        String item = "singleItem";
        // This case passes a single object, not an array, so the rule should not apply.
        // setInitialSelections(item); 
        // This case already explicitly wraps the item in an array, so no change is needed.
        setInitialSelections(new Object[]{item}); 
    }
}
